import {runInstalledAgent} from './installed-agent.mjs';
const input=String.raw`
function frame(p,name,props={}){return Insert(p,{type:'frame',name,layout:'vertical',gap:16,alignItems:'start',width:'fill_container',height:'fit_content',...props})}
function text(p,name,content,size=14,color='#EDF7FF',props={}){return Insert(p,{type:'text',name,content,fontFamily:'Inter',fontSize:size,fill:color,textGrowth:'auto',...props})}
const screen=frame(document,'Agent B — Project dashboard',{x:1100,y:1100,width:1000,height:700,padding:48,gap:32,fill:'#0D1D2A',clip:true});
const nav=frame(screen,'Dashboard navigation',{layout:'horizontal',gap:24,alignItems:'center',justifyContent:'space_between'});text(nav,'Brand','NORTHSTAR',18,'#7BDAD3',{fontWeight:'600',letterSpacing:2});const links=frame(nav,'Navigation links',{layout:'horizontal',gap:24,alignItems:'center',width:'fit_content'});for(const label of ['Overview','Projects','Team'])text(links,label,label,13,label==='Projects'?'#EDF7FF':'#7392A8');
const intro=frame(screen,'Project introduction',{gap:8});text(intro,'Eyebrow','YOUR TEAM, IN SYNC',11,'#63BEB8',{letterSpacing:2});text(intro,'Heading','Make space for great work.',36,'#EDF7FF',{fontWeight:'600'});text(intro,'Description','A clear view of what matters. Three projects, one shared direction.',14,'#7C9AAF');
const projects=frame(screen,'Project list',{gap:16});for(const [title,detail,status]of [['Website refresh','Design system and experience','In progress'],['Autumn campaign','Creative direction and launch','Review'],['Customer insights','Research and opportunity mapping','Planning']]){const project=frame(projects,title+' project',{layout:'horizontal',gap:24,alignItems:'center',justifyContent:'space_between',padding:24,fill:'#152C3B',cornerRadius:12});const copy=frame(project,title+' details',{gap:8});text(copy,title+' title',title,17,'#DAF3F7',{fontWeight:'600'});text(copy,title+' description',detail,12,'#7896A9');const badge=frame(project,title+' status',{width:112,alignItems:'center',justifyContent:'center',padding:8,fill:'#244651',cornerRadius:16,gap:0});text(badge,title+' status label',status,11,'#84D8D2')}
const footer=frame(screen,'Project footer',{layout:'horizontal',gap:24,alignItems:'center',justifyContent:'space_between'});text(footer,'Last updated','Updated just now · All changes saved',11,'#64869A');text(footer,'New project action','+ New project',13,'#75D8CE',{fontWeight:'600'});Print('AGENT_B_FRAME:'+screen);
`;
const receipt=await runInstalledAgent({hostFile:process.argv[2],agent:'agent-b',input});
console.log(JSON.stringify({agent:receipt.agent,sessionId:receipt.sessionId,openToModificationMs:receipt.openToModificationMs,result:receipt.result.content?.filter(c=>c.type==='text').map(c=>c.text).join('\n').slice(-500)}));
